import sys
from collections import deque
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    edges = []
    for i in range(m):
        p, q = map(int, lines[3+i].split())
        p -= 1
        q -= 1
        edges.append((p, q))

    # Adjacency set for quick lookup
    adj = [set() for _ in range(n)]
    for p, q in edges:
        adj[p].add(q)
        adj[q].add(p)

    total_s = sum(a)
    total_b = sum(b)

    if total_s != total_b:
        return "NO"

    # Build flow network
    source = n
    sink = n + 1

    # Graph representation: graph[u] = [[v, cap, rev], ...]
    graph = [[] for _ in range(sink + 1)]

    def add_edge(u, v, cap):
        graph[u].append([v, cap, len(graph[v])])
        graph[v].append([u, 0, len(graph[u]) - 1])

    for i in range(n):
        add_edge(source, i, a[i])
        add_edge(i, sink, b[i])
        # Self edge (stay)
        add_edge(i, i, float('inf'))
        # Neighbor edges
        for neighbor in adj[i]:
            if neighbor != i:
                add_edge(i, neighbor, float('inf'))

    # Dinic's algorithm
    level = []
    ptr = []

    def bfs():
        nonlocal level
        level = [-1] * (sink + 1)
        level[source] = 0
        q = deque([source])
        while q:
            u = q.popleft()
            for v, cap, _ in graph[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[sink] >= 0

    def dfs(u, pushed):
        if pushed == 0 or u == sink:
            return pushed
        for i in range(ptr[u], len(graph[u])):
            ptr[u] = i
            v, cap, rev = graph[u][i]
            if level[v] != level[u] + 1 or cap == 0:
                continue
            tr = dfs(v, min(pushed, cap))
            if tr == 0:
                continue
            graph[u][i][1] -= tr
            graph[v][rev][1] += tr
            return tr
        return 0

    flow = 0
    while bfs():
        ptr = [0] * (sink + 1)
        while True:
            pushed = dfs(source, float('inf'))
            if pushed == 0:
                break
            flow += pushed

    if flow != total_s:
        return "NO"

    # Build movement matrix
    matrix = [[0] * n for _ in range(n)]

    for i in range(n):
        for j, edge in enumerate(graph[i]):
            if edge[0] == source:
                continue
            elif edge[0] == sink:
                continue
            else:
                target = edge[0]
                if target < n:
                    # Forward flow (from city i to city target)
                    matrix[i][target] = graph[i][j][1]

    result = []
    for row in matrix:
        result.append(' '.join(map(str, row)) + ' ')

    return "YES\n" + '\n'.join(result)
