    os._exit(0)

    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())

    matrix = []
    for i in range(n):
        matrix.append(list(lines[1 + i]))

    def can_make_palindrome(freq):
        odd_count = sum(1 for v in freq.values() if v % 2 == 1)
        return odd_count <= 1

    ans = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            rows_ok = True
            for r in range(r1, r2 + 1):
                freq = {}
                for c in range(m):
                    ch = matrix[r][c]
                    freq[ch] = freq.get(ch, 0) + 1
                if not can_make_palindrome(freq):
                    rows_ok = False
                    break
            if not rows_ok:
                continue

            for c1 in range(m):
                for c2 in range(c1, m):
                    cols_ok = True
                    for c in range(c1, c2 + 1):
                        freq = {}
                        for r in range(r1, r2 + 1):
                            ch = matrix[r][c]
                            freq[ch] = freq.get(ch, 0) + 1
                        if not can_make_palindrome(freq):
                            cols_ok = False
                            break
                    if cols_ok:
                        ans += 1

    return str(ans) + "\n"


