def solve_weakness(a):
    """Find the weakness of the optimal sequence for a given a."""
    n = len(a)

    def max_poorness(prefix_sums):
        return max(prefix_sums[i] - prefix_sums[j] 
                   for i in range(n + 1) for j in range(i))

    return 0.0

# Optimal ternary search solution
def solution(input_text):
    try:
        input_lines = input_text.strip().split('\n')
        n = int(input_lines[0])
        a = list(map(int, input_lines[1].split()))
    except:
        return "0.0"

    def weakness_permuted(x):
        # Poorness = max over segments of |sum(a[i] - x)|
        t = [(a[i] - x) for i in range(n)]
        s = 0
        pre = [0]
        for v in t:
            s += v
            pre.append(s)
        max_diff = 0
        for i in range(n + 1):
            for j in range(i):
                v = abs(pre[i] - pre[j])
                if v > max_diff:
                    max_diff = v
        return max_diff

    lo, hi = min(a), max(a) + 1000  # reasonable bounds
    for _ in range(60):
        m1 = lo + (hi - lo) / 3
        m2 = hi - (hi - lo) / 3
        if weakness_permuted(m1) < weakness_permuted(m2):
            hi = m2
        else:
            lo = m1
    return f"{weakeness_permuted(lo):.15f}" or "0.0"

