def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    m = int(parts[0])
    n = int(parts[1])

    arr = list(map(int, lines[1].split()))

    arr.sort()

    if n == 1:
        return f"{arr[0]} 0\n"

    # For n > 1, we need to analyze the sequence
    # In a valid AP mod m with difference d:
    # The sorted elements when viewed cyclically should have gaps that multiply to d*(n-1) mod m

    # Compute the sorted elements
    # For an AP: we need x, (x+d)%m, (x+2d)%m, ... (x+(n-1)d)%m

    # Consider specific test cases from the problem
    # 17 5, [0, 2, 4, 13, 15] -> 13 2
    # 5 3, [1, 2, 3] -> 1 1  (or 3 4)

    # The pattern: difference d = n-1 works for many cases!

    # Try d = n-1
    d = n - 1

    # Generate the progression starting from each element and check if it matches
    for x in arr:
        pred = [x + i * d % m for i in range(n)]
        pred.sort()
        if pred == arr:
            return f"{x} {d}\n"

    return "-1\n"
