# Main solution that solves the stable roommates problem
def solution(input_text):
    from itertools import combinations

    lines = input_text.strip().split('\n')
    n = int(lines[0])

    # Parse cost matrix
    costs = []
    for i in range(n):
        row = list(map(int, lines[i + 1].split()))
        # row has N-1 elements, skipping diagonal
        adj = [0] * n
        for j in range(n):
            if j == i:
                adj[j] = float('inf')
            elif j < i:
                adj[j] = row[j - 1]
            else:
                adj[j] = row[j]
        costs.append(adj)

    # Generate all perfect matchings for n cities
    def generate_all_matchings(nodes):
        """Generate all perfect matchings (pairings) for given n nodes"""
        if len(nodes) == 0:
            yield []
            return

        # Pick first node and pair with any remaining
        first = nodes[0]
        for i in range(1, len(nodes)):
            second = nodes[i]
            remainder = [x for j, x in enumerate(nodes) if j != i and x != first]
            for suffix in generate_all_matchings(remainder):
                yield [(first, second)] + suffix

    # Check if a matching is stable
    def is_stable(matching):
        """Check if matching has no blocking pairs"""
        partner = {}
        for i, j in matching:
            partner[i] = j
            partner[j] = i

        for i in range(n):
            for j in range(i + 1, n):
                # Already matched?
                if partner.get(i) == j:
                    continue

                # Check blocking pair condition:
                # Both i and j prefer each other over their current partners
                cur_i = partner.get(i, -1)
                cur_j = partner.get(j, -1)

                # Cost for i to connect with j vs current partner
                cost_ij = costs[i][j] if j < n else float('inf')
                cost_ich = costs[i][cur_i] if cur_i >= 0 else float('inf')

                # Cost for j to connect with i vs current partner
                cost_ji = costs[j][i] if i < n else float('inf')
                cost_jch = costs[j][cur_j] if cur_j >= 0 else float('inf')

                # Blocking pair if both prefer each other
                if cost_ij < cost_ich and cost_ji < cost_jch:
                    return False

        return True

    # Convert matching to output format (each city's partner, 1-indexed)
    def matching_to_output(matching):
        partner = {}
        for i, j in matching:
            partner[i + 1] = j + 1
            partner[j + 1] = i + 1

        result = []
        for i in range(1, n + 1):
            result.append(str(partner[i]))
        return '\n'.join(result) + '\n'

    # Try all perfect matchings
    nodes = list(range(n))
    for matching in generate_all_matchings(nodes):
        if is_stable(matching):
            return matching_to_output(matching)

    return "-1\n"

