import sys
from itertools import combinations

def solution(input_text):
    lines = input_text.strip().split('\n')
    n = int(lines[0])

    if n < 2:
        return "-1\n"

    # Parse cost matrix
    costs = []
    for i in range(n):
        row = list(map(int, lines[i + 1].split()))
        adj = [0] * n
        for j in range(n):
            if j == i:
                adj[j] = float('inf')
            elif j < i:
                adj[j] = row[j - 1]
            else:
                adj[j] = row[j]
        costs.append(adj)

    # Generate all perfect matchings
    def gen_matchings(nodes):
        if not nodes:
            yield []
            return
        first, *others = nodes
        for second, *rest in combinations(others, 1):
            for suffix in gen_matchings(rest + [x for x in others if x != second]):
                yield [(first, second)] + suffix

    # Check stability
    def stable(match):
        p = {}
        for i, j in match:
            p[i] = j; p[j] = i
        for i in range(n):
            for j in range(i + 1, n):
                if p.get(i) == j:
                    continue
                ci, cj = p.get(i, -1), p.get(j, -1)
                if costs[i][j] < costs[i][ci] and costs[j][i] < costs[j][cj]:
                    return False
        return True

    for m in gen_matchings(range(n)):
        if stable(m):
            return '\n'.join(str(p[i+1]) for i in range(n)) + '\n'
    return "-1\n"
