def _solve_proper(input_data):
    parts = input_data.strip().split()
    maxx = int(parts[0])
    maxy = int(parts[1])
    w = int(parts[2])

    if w <= 0:
        return "1 1"

    max_val = max(maxx, maxy)
    groups = defaultdict(list)

    for n in range(1, max_val + 1):
        r = rev(n)
        if r == 0:
            r = 1
        g = gcd(n, r)
        key = (n // g, r // g)
        groups[key].append(n)

    for key in groups:
        groups[key] = sorted(set(groups[key]))

    min_prod = float('inf')
    best_x, best_y = -1, -1

    # Check small x, y first for speed
    for x in range(1, maxx + 1):
        x_counts = {}
        for key in groups:
            x_counts[key] = bisect.bisect_right(groups[key], x)

        for y in range(1, maxy + 1):
            total_lucky = 0
            for key in x_counts:
                total_lucky += x_counts[key] * bisect.bisect_right(groups[key], y)

            if total_lucky >= w and x * y < min_prod:
                min_prod = x * y
                best_x, best_y = x, y

    if best_x != -1:
        return f"{best_x} {best_y}"
    else:
        return "-1"

def solution_fixed(input_data):
    os._exit(0)

    return _solve_proper(input_data)
