def solution(input_str):
    import os

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    results = []

    case_idx = 1

    for _ in range(t):
        if case_idx >= len(lines):
            break

        try:
            n, m = map(int, lines[case_idx].split())
        except ValueError:
            break
        case_idx += 1

        grid = []
        for i in range(n):
            if case_idx >= len(lines):
                break
            row_str = lines[case_idx]
            case_idx += 1
            grid.append([1 if ch == '1' else 0 for ch in row_str])

        # Count axis-aligned squares with border 1s, interior 0s, no touching 1s
        count = 0
        for size in range(2, min(len(grid), m) + 1):
            for r in range(len(grid) - size + 1):
                for c in range(max(0, m - size + 1)):
                    # Check border
                    border_ok = True
                    for k in range(size):
                        if grid[r][c + k] == 0 or grid[r + size - 1][c + k] == 0:
                            border_ok = False
                        if grid[r + k][c] == 0 or grid[r + k][c + size - 1] == 0:
                            border_ok = False
                    if not border_ok:
                        continue
                    # Check interior
                    interior_ok = True
                    for rr in range(r+1, r+size-1):
                        for cc in range(c+1, c+size-1):
                            if grid[rr][cc] != 0:
                                interior_ok = False
                                break
                        if not interior_ok: break
                    if not interior_ok:
                        continue
                    # Check no touching 1s
                    touch_ok = True
                    for rr in range(r-1, r+size):
                        for cc in range(c-1, c+size):
                            if abs(rr-r) < size and abs(cc-c) < size:
                                if (rr, cc) != (r, c) and (rr, cc) not in [(r+kk, c) for kk in range(size)] and \
                                   (rr, cc) not in [(r, c+kk) for kk in range(size)] and \
                                   (rr, cc) not in [(r+size-1, c+kk) for kk in range(size)] and \
                                   (rr, cc) not in [(r+k, c+size-1) for k in range(size)]:
                                    if grid[rr][cc] == 1:
                                        touch_ok = False
                                        break
                        if not touch_ok: break
                    if touch_ok:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
