            for _ in range(n):
                val_str = next(iterator, None)
                if val_str is None:
                    break
                arr.append(int(val_str))

            # Find distinct values and sort them
            distinct_vals = sorted(set(arr))

            # Track min and max positions for each value
            min_pos = {}
            max_pos = {}
            for i, val in enumerate(arr):
                if val not in min_pos:
                    min_pos[val] = i
                    max_pos[val] = i
                else:
                    max_pos[val] = i

            # Find the longest contiguous subsegment of distinct values
            # where each consecutive pair (u[i], u[i+1]) satisfies max_pos[u[i]] < min_pos[u[i+1]]
            longest = 1
