from collections import deque

def edge_to_adj(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def bfs_distances(n, adj, start):
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist, None

def find_farthest(n, adj, start):
    dist, parent = bfs_distances(n, adj, start)
    mx = -1
    farthest = start
    for i in range(1, n + 1):
        if dist[i] > mx:
            mx = dist[i]
            farthest = i
    return farthest, dist, parent

def get_path(n, adj, x, y, parent):
    path = []
    curr = y
    while curr != x:
        path.append(curr)
        curr = parent[curr]
    path.append(x)
    return path[::-1]

