# Your solution code here
def solution(input_str):
    n, k, l = map(int, input_str.split())
    M = 998244353

    # Precompute factorials and inverse factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % M

    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], M - 2, M)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % M

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % M * inv_fact[n - r] % M

    def multiply_poly(p, q):
        if not p or not q:
            return [0]
        res_len = len(p) + len(q) - 1
        result = [0] * res_len
        for i in range(len(p)):
            for j in range(len(q)):
                result[i + j] = (result[i + j] + p[i] * q[j]) % M
        return result

    def get_inverse(n):
        return pow(n, M - 2, M)

    def integrate_poly(coeffs):
        total = 0
        for i, coeff in enumerate(coeffs):
            total = (total + coeff * get_inverse(i + 1)) % M
        return total

    poly_2x = [0, 2, -2]  # Represents: 2x - 2x^2
    poly_1 = [1, -2, 2]   # Represents: 1 - 2x + 2x^2

    def poly_pow(coeffs, exp):
        result = [1]
        base = list(coeffs)
        while exp > 0:
            if exp & 1:
                result = multiply_poly(result, base)
            base = multiply_poly(base, base)
            exp >>= 1
        return result

    total = 0
    for j in range(k, n + 1):
        coeff = nCr(n, j)

        poly_p = poly_pow(poly_2x, j)
        poly_q = poly_pow(poly_1, n - j)

        poly_mult = multiply_poly(poly_p, poly_q)

        term_integral = integrate_poly(poly_mult)
        total = (total + coeff * term_integral) % M

    result = (total * l) % M
    return str(result)


