            if root in seen_roots:
                continue
            seen_roots.add(root)

            # Count all edges from this component
            targets = set(adj[u])
            for v in adj[u]:
                if v in adj:
                    targets.update(adj[v])

            # Add edges count + 1 if needed
            edges = sum(len(adj[k]) for k in adj if find(k) == root)
            ops += edges

    return '\n'.join(results)
