def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    out = []

    idx = 1
    for _ in range(t):
        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1
        a = lines[idx]
        idx += 1
        b = lines[idx]
        idx += 1

        if a == b:
            out.append('0')
            continue

        adj = defaultdict(set)
        for i in range(n):
            u = ord(a[i]) - ord('a')
            v = ord(b[i]) - ord('a')
            if u != v:
                adj[u].add(v)

        # Union-find
        parent = list(range(20))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        for u in adj:
            for v in adj[u]:
                union(u, v)

        # Count components
        visited = set()
        total = 0
        for u in adj:
            r = find(u)
            if r in visited:
                continue
            visited.add(r)

            comp_chars = set()
            q = [u]
            while q:
                curr = q.pop()
                if curr in comp_chars:
                    continue
                comp_chars.add(curr)
                if curr in adj:
                    for v in adj[curr]:
                        if v not in comp_chars:
                            q.append(v)

            comp_nodes = comp_chars
            comp_targets = set()
            for c in comp_nodes:
                comp_targets.update(adj.get(c, set()))

            total += len(comp_targets)

        out.append(str(total))

    return '\n'.join(out)
